from fastapi.security import OAuth2PasswordRequestForm

@app.post("/token")
def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]) -> Token:
    user = authenticate_user(form.username, form.password)
    if user is None:
        raise HTTPException(status_code=401, detail="Incorrect username or password",
                            headers={"WWW-Authenticate": "Bearer"})
    token = create_access_token(user.username, timedelta(minutes=30))
    return Token(access_token=token, token_type="bearer")

import os
from datetime import datetime, timedelta, timezone
import jwt

SECRET_KEY = os.environ["SECRET_KEY"]  # never in code
ALGORITHM = "HS256"

def create_access_token(username: str, expires: timedelta) -> str:
    payload = {"sub": username, "exp": datetime.now(timezone.utc) + expires}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

CurrentUser = Annotated[User, Depends(get_current_user)]

